// checkTiers accepts a plan without tiers, or a metered plan whose tiers are sorted by UpTo, strictly ascending, with
// only the last tier unlimited.
func checkTiers(p Plan) error {
	if p.TiersMode == "" && len(p.Tiers) == 0 {
		return nil
	}
	switch {
	case p.UsageType != Metered:
		return badTiers("only a metered plan can have tiers")
	case p.TiersMode != Graduated && p.TiersMode != Volume:
		return badTiers("tiers_mode is graduated or volume")
	case len(p.Tiers) == 0:
		return badTiers("a tiered plan needs at least one tier")
	}
	var prev int64
	for i, t := range p.Tiers {
		last := i == len(p.Tiers)-1
		switch {
		case t.UnitAmount < 0 || t.FlatAmount < 0:
			return badTiers("a tier's amounts cannot be negative")
		case last && t.UpTo != nil:
			return badTiers("the last tier has no up_to")
		case !last && t.UpTo == nil:
			return badTiers("only the last tier has no up_to")
		case t.UpTo != nil && *t.UpTo <= prev:
			return badTiers("up_to is a positive whole number, and each tier's is above the one before")
		}
		if t.UpTo != nil {
			prev = *t.UpTo
		}
	}
	return nil
}

func badTiers(format string, args ...any) error {
	return fmt.Errorf("%w: %s", ErrInvalidTiers, fmt.Sprintf(format, args...))
}

