// checkTiers accepts a plan without tiers, or a metered plan whose tiers are sorted by UpTo, strictly ascending, with
// only the last tier unlimited.
func checkTiers(p Plan) error {
	if p.TiersMode == "" && len(p.Tiers) == 0 {
		return nil
	}
	switch {
	case p.UsageType != Metered:
		return badTiers("only a metered plan can have tiers")
	case p.TiersMode != Graduated && p.TiersMode != Volume:
		return badTiers("tiers_mode is graduated or volume")
	case len(p.Tiers) == 0:
		return badTiers("a tiered plan needs at least one tier")
	}
	var prev int64
	for i, t := range p.Tiers {
		last := i == len(p.Tiers)-1
		switch {
		case t.UnitAmount < 0 || t.FlatAmount < 0:
			return badTiers("a tier's amounts cannot be negative")
		case last && t.UpTo != nil:
			return badTiers("the last tier has no up_to")
		case !last && t.UpTo == nil:
			return badTiers("only the last tier has no up_to")
		case t.UpTo != nil && *t.UpTo <= prev:
			return badTiers("up_to is a positive whole number, and each tier's is above the one before")
		}
		if t.UpTo != nil {
			prev = *t.UpTo
		}
	}
	return nil
}

func badTiers(format string, args ...any) error {
	return fmt.Errorf("%w: %s", ErrInvalidTiers, fmt.Sprintf(format, args...))
}

// Plan returns one of an organization's plans.
func (s *Store) Plan(orgID, id string) (Plan, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	p, ok := s.plans[id]
	if !ok || p.OrgID != orgID {
		return Plan{}, false
	}
	return copyPlan(p), true
}

// Plans returns an organization's plans, oldest first.
func (s *Store) Plans(orgID string) []Plan {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Plan{}
	for _, p := range s.plans {
		if p.OrgID == orgID {
			out = append(out, copyPlan(p))
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// UpdatePlan changes a plan with f. Its currency, price, interval, usage type and tiers cannot change once created:
// subscriptions depend on them.
func (s *Store) UpdatePlan(orgID, id string, f func(*Plan) error) (Plan, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.plans[id]
	if !ok || old.OrgID != orgID {
		return Plan{}, ErrNotFound
	}
	p := copyPlan(old)
	if err := f(&p); err != nil {
		return Plan{}, err
	}
	p.ID, p.OrgID, p.CreatedAt = old.ID, old.OrgID, old.CreatedAt
	p.Currency, p.UnitAmount, p.Interval, p.UsageType = old.Currency, old.UnitAmount, old.Interval, old.UsageType
	p.TiersMode, p.Tiers = old.TiersMode, copyTiers(old.Tiers)
	p.Name = strings.TrimSpace(p.Name)
	if err := checkPlan(p); err != nil {
		return Plan{}, err
	}
	s.plans[id] = p
	return copyPlan(p), nil
}

// copyPlan is a copy of p whose tiers cannot change the stored plan's.
func copyPlan(p Plan) Plan {
	p.Tiers = copyTiers(p.Tiers)
	return p
}

func copyTiers(tiers []Tier) []Tier {
	if tiers == nil {
		return nil
	}
	out := make([]Tier, len(tiers))
	for i, t := range tiers {
		if t.UpTo != nil {
			up := *t.UpTo
			t.UpTo = &up
		}
		out[i] = t
	}
	return out
}

