// TieredAmount is the charge, in minor units, for quantity units of a metered plan's usage. Graduated mode prices each unit
// at the tier it falls in and adds the flat amount of every tier that a unit falls in. Volume mode prices every unit at the
// tier the total falls in and adds that tier's flat amount. A tier's UpTo is inclusive, and a quantity of 0 costs 0. The
// tiers must be valid (see store.Plan); a quantity beyond the last tier's UpTo is not charged.
func TieredAmount(tiers []store.Tier, mode store.TiersMode, quantity int64) int64 {
	if quantity <= 0 {
		return 0
	}
	var total int64
	switch mode {
	case store.Graduated:
		var floor int64 // the units covered by the tiers before this one
		for _, t := range tiers {
			if quantity <= floor {
				break
			}
			top := quantity
			if t.UpTo != nil && *t.UpTo < top {
				top = *t.UpTo
			}
			total += (top-floor)*t.UnitAmount + t.FlatAmount
			if t.UpTo == nil {
				break
			}
			floor = *t.UpTo
		}
	case store.Volume:
		for _, t := range tiers {
			if t.UpTo == nil || quantity <= *t.UpTo {
				return quantity*t.UnitAmount + t.FlatAmount
			}
		}
	}
	return total
}

