// tierIn is a tier as a request gives it: amounts in major units, as strings ("0.10"). FlatAmount may be left out.
type tierIn struct {
	UpTo       *json.Number `json:"up_to"`
	UnitAmount string       `json:"unit_amount"`
	FlatAmount string       `json:"flat_amount"`
}

// tiersFrom converts a request's tiers to minor units. A tier that cannot be read is invalid_tiers.
func tiersFrom(in []tierIn) ([]store.Tier, error) {
	var out []store.Tier
	for _, t := range in {
		var tier store.Tier
		if t.UpTo != nil {
			up, err := strconv.ParseInt(t.UpTo.String(), 10, 64)
			if err != nil {
				return nil, fmt.Errorf("%w: up_to is a whole number or null", store.ErrInvalidTiers)
			}
			tier.UpTo = &up
		}
		var err error
		if tier.UnitAmount, err = money.ParseMajor(t.UnitAmount, money.Currency(currencyOf(in))); err != nil {
			return nil, fmt.Errorf("%w: unit_amount %v", store.ErrInvalidTiers, err)
		}
		if t.FlatAmount != "" {
			if tier.FlatAmount, err = money.ParseMajor(t.FlatAmount, money.Currency(currencyOf(in))); err != nil {
				return nil, fmt.Errorf("%w: flat_amount %v", store.ErrInvalidTiers, err)
			}
		}
		out = append(out, tier)
	}
	return out, nil
}

// createPlan takes the price in major units, as a string ("12.50"), the way people type it. A plan with tiers does not need a
// price.
func (s *Server) createPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name      string          `json:"name"`
		Currency  money.Currency  `json:"currency"`
		Price     string          `json:"price"`
		Interval  store.Interval  `json:"interval"`
		UsageType store.UsageType `json:"usage_type"`
		TiersMode store.TiersMode `json:"tiers_mode"`
		Tiers     []tierIn        `json:"tiers"`
		TrialDays int             `json:"trial_days"`
	}
	if !decode(w, r, &in) {
		return
	}
	tiered := in.TiersMode != "" || len(in.Tiers) > 0
	var amount int64
	if !tiered || in.Price != "" {
		var err error
		amount, err = money.ParseMajor(in.Price, in.Currency)
		if err != nil {
			if errors.Is(err, money.ErrInvalidAmount) {
				writeError(w, http.StatusUnprocessableEntity, "invalid_amount", err.Error())
				return
			}
			s.storeError(w, err)
			return
		}
	}
	tiers, err := tiersFrom(in.Tiers)
	if err != nil {
		s.storeError(w, err)
		return
	}
	pl, err := s.store.CreatePlan(store.Plan{OrgID: p.OrgID, Name: in.Name, Currency: in.Currency, UnitAmount: amount, Interval: in.Interval,
		UsageType: in.UsageType, TiersMode: in.TiersMode, Tiers: tiers, TrialDays: in.TrialDays}, s.clock.Now())

