package store

import (
	"errors"
	"testing"

	"example.com/tally/internal/money"
)

func TestPlanTiers(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	up := func(n int64) *int64 { return &n }
	plan := func(usage UsageType, mode TiersMode, tiers ...Tier) Plan {
		return Plan{OrgID: o.ID, Name: "API", Currency: money.USD, Interval: Monthly, UsageType: usage, TiersMode: mode, Tiers: tiers}
	}

	for _, p := range []Plan{
		plan(Metered, Graduated, Tier{UpTo: up(10), UnitAmount: 100}, Tier{UnitAmount: 50, FlatAmount: 500}),
		plan(Metered, Volume, Tier{UnitAmount: 80}),
	} {
		if _, err := s.CreatePlan(p, t0); err != nil {
			t.Errorf("CreatePlan(%+v) = %v", p.Tiers, err)
		}
	}

	for _, c := range []struct {
		name string
		p    Plan
	}{
		{"licensed with tiers", plan(Licensed, Graduated, Tier{UnitAmount: 100})},
		{"tiers without a mode", plan(Metered, "", Tier{UnitAmount: 100})},
		{"unknown mode", plan(Metered, "stairs", Tier{UnitAmount: 100})},
		{"mode without tiers", plan(Metered, Volume)},
		{"no tiers and no mode, but an empty list", Plan{OrgID: o.ID, Name: "X", Currency: money.USD, Interval: Monthly, UsageType: Metered, Tiers: []Tier{}}},
		{"last tier has an up_to", plan(Metered, Graduated, Tier{UpTo: up(10), UnitAmount: 100})},
		{"middle tier has no up_to", plan(Metered, Graduated, Tier{UnitAmount: 100}, Tier{UnitAmount: 50})},
		{"up_to not ascending", plan(Metered, Graduated, Tier{UpTo: up(20), UnitAmount: 100}, Tier{UpTo: up(10), UnitAmount: 50}, Tier{UnitAmount: 10})},
		{"up_to repeated", plan(Metered, Graduated, Tier{UpTo: up(10), UnitAmount: 100}, Tier{UpTo: up(10), UnitAmount: 50}, Tier{UnitAmount: 10})},
		{"up_to zero", plan(Metered, Graduated, Tier{UpTo: up(0), UnitAmount: 100}, Tier{UnitAmount: 50})},
		{"negative up_to", plan(Metered, Graduated, Tier{UpTo: up(-5), UnitAmount: 100}, Tier{UnitAmount: 50})},
		{"negative unit amount", plan(Metered, Graduated, Tier{UnitAmount: -1})},
		{"negative flat amount", plan(Metered, Volume, Tier{UnitAmount: 1, FlatAmount: -1})},
	} {
		if _, err := s.CreatePlan(c.p, t0); !errors.Is(err, ErrInvalidTiers) {
			t.Errorf("%s: CreatePlan = %v, want ErrInvalidTiers", c.name, err)
		}
	}
}

func TestPlanTiersAreCopied(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	upTo := int64(10)
	tiers := []Tier{{UpTo: &upTo, UnitAmount: 100}, {UnitAmount: 50}}
	created, err := s.CreatePlan(Plan{OrgID: o.ID, Name: "API", Currency: money.USD, Interval: Monthly, UsageType: Metered, TiersMode: Graduated, Tiers: tiers}, t0)
	if err != nil {
		t.Fatal(err)
	}
	upTo, tiers[1].UnitAmount = 999, 999
	*created.Tiers[0].UpTo = 777

	got, _ := s.Plan(o.ID, created.ID)
	if *got.Tiers[0].UpTo != 10 || got.Tiers[1].UnitAmount != 50 {
		t.Fatalf("stored tiers changed: %+v", got.Tiers)
	}
	*got.Tiers[0].UpTo = 555
	if again, _ := s.Plan(o.ID, created.ID); *again.Tiers[0].UpTo != 10 {
		t.Fatalf("a read changed stored tiers: %+v", again.Tiers)
	}
}

func TestUpdatePlanCannotChangeTiers(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	upTo := int64(10)
	p, err := s.CreatePlan(Plan{OrgID: o.ID, Name: "API", Currency: money.USD, Interval: Monthly, UsageType: Metered, TiersMode: Graduated,
		Tiers: []Tier{{UpTo: &upTo, UnitAmount: 100}, {UnitAmount: 50}}}, t0)
	if err != nil {
		t.Fatal(err)
	}
	got, err := s.UpdatePlan(o.ID, p.ID, func(p *Plan) error {
		p.Name, p.TiersMode, p.Tiers = "Renamed", Volume, nil
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	if got.Name != "Renamed" || got.TiersMode != Graduated || len(got.Tiers) != 2 || *got.Tiers[0].UpTo != 10 {
		t.Fatalf("UpdatePlan = %+v; the name should change and the tiers should not", got)
	}
}

