package billing

import (
	"testing"

	"example.com/tally/internal/store"
)

// testTiers are: up to 10 at 100 plus 200 flat; 11 to 50 at 80 plus 500 flat; from 51 at 50.
func testTiers() []store.Tier {
	up10, up50 := int64(10), int64(50)
	return []store.Tier{
		{UpTo: &up10, UnitAmount: 100, FlatAmount: 200},
		{UpTo: &up50, UnitAmount: 80, FlatAmount: 500},
		{UnitAmount: 50},
	}
}

func TestTieredAmountGraduated(t *testing.T) {
	for _, c := range []struct {
		quantity int64
		want     int64
	}{
		{0, 0},
		{1, 300},     // 1 at 100, plus the first tier's flat
		{10, 1200},   // up_to is inclusive: all ten at 100, no second tier
		{11, 1780},   // the eleventh unit at 80, plus the second tier's flat
		{50, 4900},   // 10 at 100 + 40 at 80 + both flats
		{60, 5400},   // 10 more at 50
	} {
		if got := TieredAmount(testTiers(), store.Graduated, c.quantity); got != c.want {
			t.Errorf("graduated %d = %d, want %d", c.quantity, got, c.want)
		}
	}
}

func TestTieredAmountVolume(t *testing.T) {
	for _, c := range []struct {
		quantity int64
		want     int64
	}{
		{0, 0},
		{1, 300},     // the first tier for everything: 100 + 200
		{10, 1200},   // up_to is inclusive
		{11, 1380},   // the second tier for everything: 11 * 80 + 500
		{50, 4500},   // inclusive again
		{51, 2550},   // the last tier: 51 * 50, no flat
	} {
		if got := TieredAmount(testTiers(), store.Volume, c.quantity); got != c.want {
			t.Errorf("volume %d = %d, want %d", c.quantity, got, c.want)
		}
	}
}

func TestTieredAmountSingleUnlimitedTier(t *testing.T) {
	tiers := []store.Tier{{UnitAmount: 7}}
	if got := TieredAmount(tiers, store.Graduated, 3); got != 21 {
		t.Errorf("graduated = %d, want 21", got)
	}
	if got := TieredAmount(tiers, store.Volume, 3); got != 21 {
		t.Errorf("volume = %d, want 21", got)
	}
}

