package api_test

import (
	"net/http"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

func TestTieredPlans(t *testing.T) {
	e := apitest.New(t)
	var p struct {
		store.Plan
		Price string `json:"price"`
	}
	// No price: a plan with tiers does not need one. Amounts are major units here and minor units in the answer.
	e.MustDo(http.StatusCreated, "POST", "/v1/plans", e.Acme.Key, map[string]any{
		"name": "API calls", "currency": "USD", "interval": "month", "usage_type": "metered", "tiers_mode": "graduated",
		"tiers": []map[string]any{
			{"up_to": 10, "unit_amount": "1.00", "flat_amount": "2.00"},
			{"up_to": 50, "unit_amount": "0.80"},
			{"up_to": nil, "unit_amount": "0.50"},
		},
	}, &p)
	if p.TiersMode != store.Graduated || p.UnitAmount != 0 || len(p.Tiers) != 3 {
		t.Fatalf("plan = %+v", p.Plan)
	}
	if got := p.Tiers[0]; got.UpTo == nil || *got.UpTo != 10 || got.UnitAmount != 100 || got.FlatAmount != 200 {
		t.Errorf("first tier = %+v", got)
	}
	if got := p.Tiers[1]; got.UpTo == nil || *got.UpTo != 50 || got.UnitAmount != 80 || got.FlatAmount != 0 {
		t.Errorf("second tier = %+v", got)
	}
	if got := p.Tiers[2]; got.UpTo != nil || got.UnitAmount != 50 {
		t.Errorf("last tier = %+v", got)
	}

	var got store.Plan
	e.MustDo(http.StatusOK, "GET", "/v1/plans/"+p.ID, e.Acme.Key, nil, &got)
	if got.TiersMode != store.Graduated || len(got.Tiers) != 3 || got.Tiers[0].FlatAmount != 200 {
		t.Fatalf("plan read back = %+v", got)
	}
	var raw map[string]any
	e.MustDo(http.StatusOK, "GET", "/v1/plans/"+p.ID, e.Acme.Key, nil, &raw)
	if raw["tiers_mode"] != "graduated" || raw["tiers"] == nil {
		t.Errorf("JSON fields = %v", raw)
	}
}

func TestInvalidTiers(t *testing.T) {
	e := apitest.New(t)
	tier := func(upTo any, unit string) map[string]any { return map[string]any{"up_to": upTo, "unit_amount": unit} }
	base := func(usage, mode string, tiers ...map[string]any) map[string]any {
		body := map[string]any{"name": "X", "currency": "USD", "interval": "month", "usage_type": usage, "tiers_mode": mode}
		if tiers != nil {
			body["tiers"] = tiers
		}
		return body
	}
	for name, body := range map[string]map[string]any{
		"licensed plan with tiers":   base("licensed", "graduated", tier(nil, "1.00")),
		"no tiers_mode":              base("metered", "", tier(nil, "1.00")),
		"unknown tiers_mode":         base("metered", "stairs", tier(nil, "1.00")),
		"tiers_mode without tiers":   base("metered", "volume"),
		"empty tiers":                base("metered", "volume", ),
		"last tier with up_to":       base("metered", "graduated", tier(10, "1.00")),
		"middle tier without up_to":  base("metered", "graduated", tier(nil, "1.00"), tier(nil, "0.50")),
		"up_to not ascending":        base("metered", "graduated", tier(20, "1.00"), tier(10, "0.50"), tier(nil, "0.10")),
		"up_to zero":                 base("metered", "graduated", tier(0, "1.00"), tier(nil, "0.50")),
		"up_to not whole":            base("metered", "graduated", tier(1.5, "1.00"), tier(nil, "0.50")),
		"up_to as text":              base("metered", "graduated", tier("10", "1.00"), tier(nil, "0.50")),
		"unit_amount not an amount":  base("metered", "volume", tier(nil, "abc")),
		"negative unit_amount":       base("metered", "volume", tier(nil, "-1.00")),
		"negative flat_amount":       base("metered", "volume", map[string]any{"up_to": nil, "unit_amount": "1.00", "flat_amount": "-2.00"}),
		"flat_amount not an amount":  base("metered", "volume", map[string]any{"up_to": nil, "unit_amount": "1.00", "flat_amount": "two"}),
	} {
		if r := e.Do("POST", "/v1/plans", e.Acme.Key, body); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_tiers" {
			t.Errorf("%s: %s", name, r)
		}
	}
}

func TestMeteredPlanStillNeedsAPrice(t *testing.T) {
	e := apitest.New(t)
	r := e.Do("POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "X", "currency": "USD", "interval": "month", "usage_type": "metered"})
	if r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_amount" {
		t.Fatalf("metered plan without a price or tiers: %s", r)
	}
}

