package subscriptions_test

import (
	"context"
	"strings"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
)

func TestTieredUsageIsBilledAsOneLine(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	up := int64(10)
	p, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Tiers API", Currency: money.USD, Interval: store.Monthly, UsageType: store.Metered,
		TiersMode: store.Graduated, Tiers: []store.Tier{{UpTo: &up, UnitAmount: 100, FlatAmount: 200}, {UnitAmount: 50}}}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	end := sub.CurrentPeriodEnd
	if _, err := e.Store.AddUsage(e.Acme.ID, sub.ID, 15, sub.CurrentPeriodStart, e.Clock.Now()); err != nil {
		t.Fatal(err)
	}
	e.Clock.Set(end)
	if _, err := e.Subs.RenewDue(ctx); err != nil {
		t.Fatal(err)
	}
	// 10 units at 100 plus the flat 200, then 5 units at 50: 1450.
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 1 || len(invs[0].Lines) != 1 {
		t.Fatalf("invoices = %+v", invs)
	}
	line := invs[0].Lines[0]
	if line.Quantity != 1 || line.UnitAmount != 1450 || !strings.HasPrefix(line.Description, "Tiers API usage, ") {
		t.Fatalf("line = %+v", line)
	}
	if cs := e.Gateway.Charges(); len(cs) != 1 || cs[0].Amount != 1450 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestTieredPeriodWithoutUsageIsNotInvoiced(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	up := int64(10)
	p, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Tiers API", Currency: money.USD, Interval: store.Monthly, UsageType: store.Metered,
		TiersMode: store.Volume, Tiers: []store.Tier{{UpTo: &up, UnitAmount: 100}, {UnitAmount: 50}}}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Set(sub.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 0 {
		t.Fatalf("a period without usage was invoiced: %+v", invs)
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, sub.ID); got.Status != store.Active {
		t.Fatalf("status = %s, want active", got.Status)
	}
}

